import{_ as s}from"./chunks/continuous_data_copy_diagram.DTb3IKol.js";import{_ as n}from"./chunks/discontinuous_data_copy_diagram.BevDX9nI.js";import{_ as p,o as t,a as l,b as c}from"./app.C41L12d5.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Memory矢量计算","link":"/api/SIMD-API/basic_api/memory_vector_compute/memory_vector_compute"},{"text":"数据搬运","link":"/api/SIMD-API/basic_api/memory_vector_compute/data_move/data_move"},{"text":"DataCopy（UB -> UB高维切分数据搬运）","link":"/api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopy_UBToUB_highdim_split"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopy_UBToUB_highdim_split.md","filePath":"api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopy_UBToUB_highdim_split.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),i={name:"api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopy_UBToUB_highdim_split.md"};function o(e,a,d,r,h,_){return t(),l("div",null,[...a[0]||(a[0]=[c('<div><article class="markdown-body"><h1>DataCopy（UBToUB高维切分数据搬运）<span id="ZH-CN_TOPIC_0000002382908021"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：不支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section474617392321"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_data_copy_intf.h&quot;</code>。</p><p>支持Unified Buffer（UB）内部的高维切分数据搬运，数据在传输过程中保持原始格式和内容不变。</p><p>具体支持的数据通路为（以<a href="../../aux_data_structures/TPosition.html">逻辑位置TPosition</a>表示）：</p><ul><li>UB -&gt; UB <ul><li>VECIN -&gt; VECCALC</li><li>VECCALC -&gt; VECOUT</li></ul></li></ul><p>高维切分数据搬运可通过配置数据块个数、单个数据块长度、地址偏移等搬运参数，同时支持非连续和连续的数据搬运。</p><h2 id="函数原型">函数原型<span id="section1954364615315"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>\n<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">DataCopyParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">)</span>\n</code></pre></div><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th align="left">参数名</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">T</td><td align="left">操作数的数据类型。支持的数据类型请参考<a href="#section4219135304818">数据类型</a>。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th align="left">参数名</th><th align="center">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">dst</td><td align="center">输出</td><td align="left">目的操作数，类型为<a href="../../data_structures/LocalTensor/LocalTensor_intro.html">LocalTensor</a>，存储位置为UB，目的地址需要32字节对齐。</td></tr><tr><td align="left">src</td><td align="center">输入</td><td align="left">源操作数，类型为LocalTensor，存储位置为UB，源地址需要32字节对齐。</td></tr><tr><td align="left">repeatParams</td><td align="center">输入</td><td align="left">搬运参数，DataCopyParams类型，参数说明请参考表3。通过该参数可配置搬运的数据块大小、个数、间隔等信息，同时支持非连续和连续搬运。<br>具体定义请参考<code>${INSTALL_DIR}/asc/include/basic_api/kernel_struct_data_copy.h</code>，<code>${INSTALL_DIR}</code>请替换为CANN软件安装后文件存储路径。</td></tr></tbody></table><p><strong>表3</strong> DataCopyParams结构体参数定义</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>blockCount</td><td>搬运的数据块个数，数据类型为uint16_t，取值范围：blockCount∈[0, 4095]，默认值为1。</td></tr><tr><td>blockLen</td><td>搬运的每个数据块长度，数据类型为uint16_t，取值范围：blockLen∈[0, 65535]，单位：DataBlock（32B）。</td></tr><tr><td>srcGap</td><td>源操作数相邻数据块之间的间隔（即前一个数据块<strong>结束地址</strong>与后一个数据块<strong>起始地址</strong>的差值），数据类型为uint16_t，取值范围：srcGap∈[0, 65535]，单位：DataBlock（32B）。<br>• blockCount = 1时，srcGap无意义，设置为0即可。</td></tr><tr><td>dstGap</td><td>目的操作数相邻数据块之间的间隔（即前一个数据块<strong>结束地址</strong>与后一个数据块<strong>起始地址</strong>的差值），数据类型为uint16_t，取值范围：dstGap∈[0, 65535]，单位：DataBlock（32B）。<br>• blockCount = 1时，dstGap无意义，设置为0即可。</td></tr></tbody></table><p>下面的样例通过两个示例展示连续搬运和非连续搬运的使用方式。</p><p>针对连续搬运场景，推荐使用<a href="DataCopy_UBToUB_continuous.html#ZH-CN_TOPIC_0000002382908021">DataCopy(UBToUB连续数据搬运)</a>，以下示例仅展示高维切分数据搬运接口具有连续搬运能力。</p><ul><li><p>示例1：连续搬运</p><p>以half数据类型为例，源操作数的shape为1 * 128。</p><p>以图1为例，将源操作数中128个元素<strong>连续</strong>搬运至目的操作数。DataCopyParams结构体参数配置如下：</p><ul><li>blockCount = 1，搬运1个数据块，表示连续搬运。</li><li>blockLen = 8，一个数据块长度为8个DataBlock。</li><li>srcGap = 0，源操作数相邻数据块之间的间隔为0。</li><li>dstGap = 0，目的操作数相邻数据块之间的间隔为0。</li></ul><p><strong>图1</strong> 连续搬运示意图<span id="zh-cn_topic_0000002535088926_fig4621152141711"></span><br><img src="'+s+'" alt title="连续搬运示意图"></p></li><li><p>示例2：非连续搬运</p><p>以half数据类型为例，源操作数的shape为1 * 112。</p><p>以图2为例，将源操作数中数据<strong>非连续</strong>搬运至目的操作数。DataCopyParams结构体参数配置如下：</p><ul><li>blockCount = 2，搬运2个数据块。</li><li>blockLen = 3，一个数据块的长度为3个DataBlock。</li><li>srcGap = 1，源操作数相邻数据块之间的间隔为1。</li><li>dstGap = 2，目的操作数相邻数据块之间的间隔为2。</li></ul><p><strong>图2</strong> 非连续搬运示意图<span id="zh-cn_topic_0000002535088926_fig422819202304"></span><br><img src="'+n+`" alt title="非连续搬运示意图"></p></li></ul><h2 id="数据类型">数据类型<span id="section4219135304818"></span><a class="header-anchor" href="#数据类型">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT，支持的数据类型为：bool、int8_t、uint8_t、hifloat8_t、fp8_e8m0_t、fp8_e5m2_t、fp8_e4m3fn_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、complex32、int64_t、uint64_t、double、complex64。</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、int64_t、uint64_t、double。</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、int64_t、uint64_t、double。</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、int32_t、uint32_t、float、int64_t、uint64_t、double。</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、int32_t、uint32_t、float、int64_t、uint64_t、double。</li></ul></div><h2 id="返回值说明">返回值说明<span id="section44801012174220"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>位于UB的地址必须32字节对齐。</li></ul><div data-filter="A3,910b,950"><ul><li>当DataCopyParams结构体参数blockCount、blockLen任意一个值为0时，该接口将被视为NOP（空操作）。该说明针对如下型号生效： <div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></div><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT</li></ul></div></li></ul></div><ul><li><p>DataCopyParams结构体参数的值需在取值范围内：</p><p><strong>表4</strong> DataCopyParams结构体参数取值范围</p><table><thead><tr><th>参数名</th><th>取值范围</th></tr></thead><tbody><tr><td>blockCount</td><td>[0, 4095]</td></tr><tr><td>blockLen</td><td>[0, 65535]</td></tr><tr><td>srcGap</td><td>[0, 65535]</td></tr><tr><td>dstGap</td><td>[0, 65535]</td></tr></tbody></table></li></ul><div data-filter="910b,A3"><ul><li><p>针对如下产品型号：</p><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li></ul><p>在跨卡通信算子开发场景，DataCopy类接口支持跨卡数据搬运，仅支持HCCS物理链路，不支持其他通路；开发者开发过程中，需要关注涉及卡间通信的物理通路，可通过<code>npu-smi info -t topo</code>命令查询HCCS物理链路。</p></li></ul></div><h2 id="调用示例">调用示例<span id="section122101199486"></span><a class="header-anchor" href="#调用示例">​</a></h2><ul><li><p>场景1：连续搬运——将源数据中128个half元素连续搬运至目的操作数（对应<a href="#zh-cn_topic_0000002535088926_fig4621152141711">图1</a>）</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// srcLocal、dstLocal为half类型的LocalTensor。</span>
<span class="c1">// 使用传入count参数的搬运接口，完成连续搬运。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="mi">128</span><span class="p">);</span>

<span class="c1">// 使用传入DataCopyParams参数的搬运接口，实现相同的连续搬运效果。</span>
<span class="c1">// blockCount = 1：连续数据块个数为1</span>
<span class="c1">// blockLen = 8：一个数据块长度为8个DataBlock（128个half元素 ÷ (32B/2B) = 8）。</span>
<span class="c1">// srcGap = 0, dstGap = 0：无间隔，连续搬运。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyParams</span><span class="w"> </span><span class="n">params</span><span class="p">;</span>
<span class="n">params</span><span class="p">.</span><span class="n">blockCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="n">params</span><span class="p">.</span><span class="n">blockLen</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span>
<span class="n">params</span><span class="p">.</span><span class="n">srcGap</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="n">params</span><span class="p">.</span><span class="n">dstGap</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">params</span><span class="p">);</span>
</code></pre></div></li><li><p>场景2：非连续搬运——从源数据中搬运2个数据块，每个数据块3个DataBlock，源间隔1个DataBlock、目的间隔2个DataBlock（对应<a href="#zh-cn_topic_0000002535088926_fig422819202304">图2</a>）</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// srcLocal、dstLocal为half类型的LocalTensor。</span>
<span class="c1">// 源数据shape为[1, 112]，共112个half元素（7个DataBlock）。</span>
<span class="c1">// 目的数据接收非连续排列的2个数据块，共6个DataBlock（96个half元素）。</span>
<span class="c1">// blockCount = 2：搬运2个数据块</span>
<span class="c1">// blockLen = 3：每个数据块长度为3个DataBlock</span>
<span class="c1">// srcGap = 1：源相邻数据块间隔1个DataBlock</span>
<span class="c1">// dstGap = 2：目的相邻数据块间隔2个DataBlock</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyParams</span><span class="w"> </span><span class="n">params</span><span class="p">;</span>
<span class="n">params</span><span class="p">.</span><span class="n">blockCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="n">params</span><span class="p">.</span><span class="n">blockLen</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">3</span><span class="p">;</span>
<span class="n">params</span><span class="p">.</span><span class="n">srcGap</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="n">params</span><span class="p">.</span><span class="n">dstGap</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">params</span><span class="p">);</span>
</code></pre></div></li></ul></article></div>`,1)])])}const A=p(i,[["render",o]]);export{f as __pageData,A as default};
